		CompoundTag kjs$getTag();

		@Accessor("tag")
		void kjs$setTag(CompoundTag tag);
	}

	public static ItemStack kjs$copyWithComponents(ItemStack original) {
		var copy = original.copy();
		copy.kjs$setComponents(original.kjs$getComponents().copy());
		return copy;
	}

	public static boolean kjs$hasComponent(ItemStack stack, DataComponentType<?> type) {
		return stack.kjs$getComponents().has(type);
	}

	public static <T> T kjs$getComponent(ItemStack stack, DataComponentType<T> type) {
		return stack.kjs$getComponents().get(type);
	}

	public static <T> void kjs$setComponent(ItemStack stack, DataComponentType<T> type, T value) {
